import type { Config } from "tailwindcss";

// Single accent hue (OKLCH degrees), taken from stock Tailwind blue-600.
// Every gray/slate/blue shade below keeps its stock lightness and chroma —
// so WCAG contrast is exactly what the v3 accessibility audit measured —
// with only the hue snapped here. Change HUE to re-theme the whole site.
// (Generated by converting tailwindcss/colors to OKLCH; the <alpha-value>
// placeholder keeps opacity modifiers like bg-white/70 working.)
const HUE = 262.9;
const o = (l: number, c: number) => `oklch(${l} ${c} ${HUE} / <alpha-value>)`;

